'use strict';
let writingDraft=null,writingBusy=false;
const hasAIKey=(provider=state.settings.aiProvider)=>provider==='gpt'?state.hasGptKey:state.hasDeepseekKey;
const aiLabel=()=>state.settings.aiProvider==='gpt'?'GPT':'DeepSeek';
const writingJournals=['Nature Communications','Nature Photonics','Journal of Lightwave Technology'];
const writingJournalKey=s=>s.trim().replace(/\s+/g,' ').toLowerCase();
function parseWritingJournals(value){
  const journals=new Map();
  for(const item of value.split(/[;；\r\n]+/).map(s=>s.trim()).filter(Boolean)){
    const name=/^nature\s+photonics?$/i.test(item)?'Nature Photonics':item,key=writingJournalKey(name);
    if(!journals.has(key))journals.set(key,name);
  }
  return [...journals.values()];
}
function writingData(){
  if(!writingDraft){
    const saved=state.settings.writing;
    const type=saved.type==='会议论文'?'会议':saved.type;
    writingDraft={...saved,type:['期刊','会议','学位论文'].includes(type)?type:'期刊',provider:saved.provider||state.settings.aiProvider,targetLanguage:saved.targetLanguage||'en',mode:'polish',original:'',result:'',journals:parseWritingJournals(saved.journals.join('; ')).join('; ')};
  }
  return writingDraft;
}
function syncWritingJournals(){
  const selected=new Set(parseWritingJournals(writingData().journals).map(writingJournalKey));
  for(const button of $$('.writing-journal-chip')){
    const active=selected.has(writingJournalKey(button.dataset.journal));
    button.classList.toggle('active',active);
    button.setAttribute('aria-pressed',String(active));
    button.innerHTML=icon(active?'check':'plus')+esc(button.dataset.journal);
  }
}
function captureWritingField(el){
  if(!el.id.startsWith('writing-')||el.id==='writing-result')return;
  const d=writingData();
  if(el.id==='writing-original')d.original=el.value;
  if(el.id==='writing-journals'){d.journals=el.value;syncWritingJournals();}
  if(el.id==='writing-type')d.type=el.value;
  if(el.id==='writing-provider')d.provider=el.value;
  if(el.id==='writing-target')d.targetLanguage=el.value;
}
function writingHTML(){
  const d=writingData(),busy=writingBusy||state.activeAi.includes('writing');
  const selected=new Set(parseWritingJournals(d.journals).map(writingJournalKey));
  return `<div class="page-heading"><div><h1>${t('writing')}</h1><p>${wx('按目标期刊与写作类型，润色或翻译你的学术文段。','Polish or translate academic passages for your target journals and writing type.')}</p></div></div>
    <div class="scroll writing-page">
      <section class="panel writing-options">
        <div class="field writing-journals-field">
          <label for="writing-journals">${wx('期刊名称（英文分号 ; 分隔）','Target journals (separated by ;)')}</label>
          <input id="writing-journals" maxlength="6030" value="${esc(d.journals)}" placeholder="Nature Communications; Nature Photonics" ${busy?'disabled':''}>
          <div class="writing-journal-options" role="group" aria-label="${wx('期刊快捷多选','Journal presets')}">
            ${writingJournals.map(j=>{const active=selected.has(writingJournalKey(j));return btn('writing-journal',j,active?'check':'plus','writing-journal-chip'+(active?' active':''),`data-journal="${esc(j)}" aria-pressed="${active}" ${busy?'disabled':''}`);}).join('')}
          </div>
        </div>
        <div class="field"><label for="writing-type">${wx('写作类型','Writing type')}</label>
          <select id="writing-type" ${busy?'disabled':''}>${option('期刊',wx('期刊','Journal'),d.type)}${option('会议',wx('会议','Conference'),d.type)}${option('学位论文',wx('学位论文','Thesis'),d.type)}</select>
        </div>
        <div class="field"><label for="writing-provider">${wx('AI 接口','AI provider')}</label>
          <select id="writing-provider" ${busy?'disabled':''}>${option('gpt','GPT (OpenAI)',d.provider)}${option('deepseek','DS (DeepSeek)',d.provider)}</select>
        </div>
      </section>
      <div class="writing-columns">
        <section class="panel"><div class="row between"><h2>${wx('原文','Original')}</h2><small class="muted">${wx('最多 30000 字符','Up to 30,000 characters')}</small></div><textarea id="writing-original" maxlength="30000" placeholder="${wx('粘贴需要处理的文段…','Paste your passage…')}" ${busy?'disabled':''}>${esc(d.original)}</textarea></section>
        <section class="panel"><div class="row between"><h2>${wx('修改后版本','Revised version')}</h2>${btn('writing-copy',wx('复制','Copy'),'','small',!d.result?'disabled':'')}</div><textarea id="writing-result" readonly placeholder="${wx('处理后的文段会显示在这里','Your revised passage appears here')}" aria-label="${wx('修改后版本','Revised version')}">${esc(d.result)}</textarea></section>
      </div>
    </div>
    <div class="writing-footer">
      <div class="writing-target"><label for="writing-target">${wx('翻译目标','Translate into')}</label><select id="writing-target" ${busy?'disabled':''}>${option('en',wx('英文','English'),d.targetLanguage)}${option('zh',wx('简体中文','Simplified Chinese'),d.targetLanguage)}</select></div>
      <span class="muted writing-status" role="status">${busy?wx('AI 正在处理…','AI is processing…'):''}</span>
      <div class="writing-actions" role="group" aria-label="${wx('写作操作','Writing actions')}">${[['polish',wx('润色','Polish')],['translate',wx('翻译','Translate')],['polish-translate',wx('润色与翻译','Polish & translate')]].map(([mode,label])=>btn('writing-generate',label,'','writing-action'+(d.mode===mode?' primary is-selected':''),`data-mode="${mode}" aria-pressed="${d.mode===mode}" aria-busy="${busy&&d.mode===mode}" ${busy?'disabled':''}`)).join('')}${busy?btn('writing-stop',t('stop'),'close','small'):''}</div>
    </div>`;
}
async function writingAction(a,b){
  if(!a.startsWith('writing-'))return false;
  if(a==='writing-stop'){await call('ai-cancel','writing');return true;}
  const d=writingData();
  if(a==='writing-journal'){
    const journals=parseWritingJournals(d.journals),key=writingJournalKey(b.dataset.journal);
    d.journals=(journals.some(j=>writingJournalKey(j)===key)?journals.filter(j=>writingJournalKey(j)!==key):[...journals,b.dataset.journal]).join('; ');
    $('#writing-journals').value=d.journals;syncWritingJournals();return true;
  }
  if(a==='writing-copy'){await navigator.clipboard.writeText(d.result);toast(wx('已复制','Copied'));return true;}
  if(a==='writing-generate'){
    if(writingBusy)return true;
    d.mode=b.dataset.mode||'polish';
    if(!d.original.trim()){render();throw Error('INVALID_WRITING_TEXT');}
    if(!hasAIKey(d.provider)){await navigate('settings');throw Error(d.provider==='gpt'?'GPT_KEY_REQUIRED':'DEEPSEEK_KEY_REQUIRED');}
    const input={original:d.original,journals:parseWritingJournals(d.journals),type:d.type,provider:d.provider,mode:d.mode,targetLanguage:d.targetLanguage};
    d.journals=input.journals.join('; ');writingBusy=true;render();
    try{d.result=await call('writing-generate',input);}
    finally{writingBusy=false;if(view==='writing')render();}
    return true;
  }
  return false;
}

