let state,view='inbox',selected=null,filter='',groupFilter='',journalFilter='',authorFilter='',tagFilter='',sort='new',page=0,draft=null,unreadOnly=false;
let authorQuery={name:'',school:'',role:'either'},activeAuthorQuery=null,authorOpen=false,toastTimer;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>dict[state?.settings.language||'zh'][k]||k;
const norm=s=>String(s||'').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');
const corr=p=>p.manualCorresponding!==null&&p.manualCorresponding!==undefined?p.manualCorresponding:p.authors.filter(a=>a.corresponding).map(a=>a.name);
const match=p=>!!p.journal&&[...state.settings.journals,...state.settings.weekly.journals].some(j=>norm(j)===norm(p.journal));
const date=(n,short=false)=>new Date(n).toLocaleString(state.settings.language==='zh'?'zh-CN':'en-US',short?{month:'short',day:'numeric'}:{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
icons['chevron-up']='<path d="m6 15 6-6 6 6"/>';icons['chevron-down']='<path d="m6 9 6 6 6-6"/>';
const btn=(action,label,ico='',cls='',extra='')=>`<button data-action="${action}" class="${cls}" ${extra}>${ico?icon(ico):''}${esc(label)}</button>`;
const option=(value,label,current)=>`<option value="${esc(value)}" ${String(current)===String(value)?'selected':''}>${esc(label)}</option>`;
function message(code){return errors[code]?.[state.settings.language==='en'?1:0]||(/^HTTP_\d+$/.test(code)?t('error')+': '+code.slice(5):String(code).slice(0,200));}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
const call=(name,...args)=>window.desk.call(name,...args);
const weeklyPaper=p=>p.weeklyRuns?.length||p.groupRefs?.some(x=>x.startsWith('weekly:'));
const researchView=()=>['inbox','weekly','all','saved'].includes(view);
const editingSettings=()=>view==='settings'||view==='schedule';
function nav(name,ico,count){return `<button class="nav ${view===name?'active':''}" data-action="nav" data-view="${name}">${icon(ico)}<span>${esc(t(name))}</span>${count!==undefined?`<span class="count">${count}</span>`:''}</button>`;}
function sidebarGroup(label,links){return '<section class="sidebar-group"><div class="workspace-label">'+esc(label)+'</div>'+links+'</section>';}
function frame(content){return `<aside class="sidebar"><div class="brand"><img src="../assets/icon.png" alt=""><span class="brand-title">PaperDesk</span></div><nav class="sidebar-navigation" aria-label="${wx('主要导航','Main navigation')}">${sidebarGroup(t('workspace'),nav('inbox','search')+nav('weekly','inbox',state.papers.filter(p=>weeklyPaper(p)&&!p.read).length)+nav('quick','chat'))}${sidebarGroup(t('quickWriting'),nav('writing','edit'))}${sidebarGroup(t('collection'),nav('all','book',state.papers.length)+nav('saved','star',state.papers.filter(p=>p.starred).length))}</nav><div class="sidebar-bottom"><div class="sidebar-links">${nav('settings','sliders')}${nav('schedule','clock')}${nav('history','history')}</div><div class="schedule-mini"><span class="dot ${state.settings.scheduleEnabled?'on':''}"></span>${t(state.settings.scheduleEnabled?'on':'off')}<small>${esc(scheduleLabel(state.settings))}</small></div><div class="local-label">${icon('shield')}${t('local')}</div></div></aside><div class="shell"><header class="topbar"><div class="crumb">PaperDesk <span>/</span><strong>${esc(t(view))}</strong></div><div class="topbar-right">${topbarTools()}</div></header><main class="content view-${view}">${content}</main></div>${modalHTML()}`;}
function progressHTML(){const p=state.progress;return state.running?`<div class="progress"><span class="spinner"></span><span>${esc(p?.phase==='metadata'?t('enriching'):`${t('processing')} ${p?.query||1}/${p?.total||1} · ${p?.page||1} ${t('page')}`)}</span>${btn('stop',t('stop'),'','ghost small')}</div>`:'';}
function statsHTML(){return `<div class="stats">${[['total',state.papers.length,'all'],['stars',state.papers.filter(p=>p.starred).length,'saved'],['new',state.papers.filter(p=>!p.read).length,'unread']].map(([k,n,v])=>`<button class="stat" data-action="${v==='unread'?'unread':'nav'}" data-view="${v}"><span class="stat-label">${t(k)}</span><span class="stat-number">${n}</span></button>`).join('')}</div>`;}
function authorSearchHTML(){return `<details class="author-search" ${authorOpen?'open':''}><summary>${icon('search')}${t('authorLookup')}</summary><div class="author-search-form"><label>${t('authorName')}<textarea id="author-name" rows="2" maxlength="1200" placeholder="${t('authorName')}">${esc(authorQuery.name)}</textarea></label><label>${t('authorSchool')}<textarea id="author-school" rows="2" maxlength="2200" placeholder="${t('authorSchool')}">${esc(authorQuery.school)}</textarea></label><label>${t('authorRole')}<select id="author-role">${option('either',t('eitherRole'),authorQuery.role)}${option('first',t('first'),authorQuery.role)}${option('corresponding',t('corr'),authorQuery.role)}</select></label>${btn('author-search',t('findAuthor'),'search','primary',state.running?'disabled':'')}</div><p class="help">${t('authorHelp')}</p></details>`;}
function groupOptions(){return [['manual',state.settings],['weekly',state.settings.weekly]].flatMap(([scope,s])=>s.groups.map((g,i)=>g.length?option(scope+':'+i,groupName(s,i)+(scope==='weekly'?' · '+t('weekly'):''),groupFilter):'')).join('');}
function filtered(){return state.papers.filter(p=>(!p.read||p.starred||p.id===selected)&&(view!=='weekly'||weeklyPaper(p))&&weeklyMatches(p)&&(view!=='saved'||p.starred)&&(!activeAuthorQuery||p.authorSearches?.some(q=>q.name===activeAuthorQuery.name&&q.school===activeAuthorQuery.school&&q.role===activeAuthorQuery.role))&&(!unreadOnly||!p.read||p.id===selected)&&(!filter||[p.title,p.abstract,p.journal,...p.authors.map(a=>a.name),...p.tags,...p.keywords].join(' ').toLowerCase().includes(filter.toLowerCase()))&&(!groupFilter||(p.groupRefs?.length?p.groupRefs.includes(groupFilter):p.groups.includes(Number(groupFilter.split(':')[1]))))&&(!journalFilter||match(p))&&(!authorFilter||(authorFilter==='__unknown'?!corr(p).length:corr(p).includes(authorFilter)))&&(!tagFilter||p.tags.includes(tagFilter))).sort((a,b)=>sort==='year'?Number(b.year)-Number(a.year)||b.addedAt-a.addedAt:b.addedAt-a.addedAt);}
function research(){const collection=view==='saved'?state.papers.filter(p=>p.starred):state.papers,authors=[...new Set(collection.flatMap(corr))],tags=[...new Set(collection.flatMap(p=>p.tags))];return `<div class="page-heading"><div><h1>${t(view)}</h1><p>${t(view==='weekly'?'weeklySub':'subtitle')}</p></div><div class="row">${panelButton()}${btn('export',t('export'),'download')}${btn(view==='weekly'?'run-weekly':'run',t(view==='weekly'?'runWeekly':'run'),'search','primary',state.running?'disabled':'')}</div></div><section id="research-tools" class="research-tools" ${toolsCollapsed()?'hidden':''}>${statsHTML()}${view==='weekly'?weeklyTools():''}${view==='inbox'?authorSearchHTML():''}<div class="toolbar"><div class="search-box">${icon('search')}<input id="filter" value="${esc(filter)}" placeholder="${t('filter')}" aria-label="${t('filter')}"></div><select id="group-filter">${option('',t('allGroups'),groupFilter)}${groupOptions()}</select><select id="journal-filter">${option('',t('anyJournal'),journalFilter)}${option('target',t('targetOnly'),journalFilter)}</select><select id="sort">${option('new',t('sortNew'),sort)}${option('year',t('sortYear'),sort)}</select>${activeAuthorQuery?btn('clear-author',activeAuthorQuery.name+' · '+activeAuthorQuery.school,'close','small'):''}${unreadOnly?btn('unread',t('unreadOnly'),'close','small'):''}</div>${['all','saved'].includes(view)?`<div class="toolbar"><select id="author-filter" aria-label="${t('allAuthors')}">${option('',t('allAuthors'),authorFilter)}${option('__unknown',t('notProvided'),authorFilter)}${authors.map(n=>option(n,n,authorFilter)).join('')}</select><select id="tag-filter" aria-label="${t('allTags')}">${option('',t('allTags'),tagFilter)}${tags.map(n=>option(n,n,tagFilter)).join('')}</select></div>`:''}</section><div id="progress-zone">${progressHTML()}</div><div class="paper-layout" id="results-zone">${results()}</div>`;}
function authorHTML(p,limit=30){const c=corr(p);return p.authors.slice(0,limit).map(a=>`<span class="author ${a.first?'first':''} ${c.includes(a.name)?'corresponding':''}" title="${a.first?t('first'):''}${c.includes(a.name)?' · '+t('corr'):''}">${esc(a.name)}${c.includes(a.name)?' ✉':''}</span>`).join('')||`<span class="muted">${t('notProvided')}</span>`;}
function card(p){const c=corr(p).join(', ')||t('notProvided'),first=p.authors.filter(a=>a.first).map(a=>a.name).join(', ')||t('notProvided');return `<article class="paper-card ${selected===p.id?'selected':''} ${p.read?'':'unread'}" data-action="select" data-id="${p.id}" tabindex="0" role="button" aria-label="${esc(p.title)}">${view==='weekly'?`<input class="week-check" type="checkbox" data-action="weekly-check" data-id="${p.id}" aria-label="${esc(u('selected')+' '+p.title)}" ${weeklySelected.has(p.id)?'checked':''}>`:''}<button class="star ${p.starred?'on':''}" data-action="star" data-id="${p.id}" aria-label="${t('saved')}" aria-pressed="${p.starred}">${icon('star')}</button><h3 class="paper-title">${esc(p.title)}</h3><div class="paper-authors-line"><span title="${esc(t('corr')+': '+c)}">${u('corrShort')}: ${esc(c)}</span><span title="${esc(t('first')+': '+first)}">${u('firstShort')}: ${esc(first)}</span></div><div class="paper-journal-line"><span class="paper-year">${esc(p.year||'—')}</span><span class="paper-journal">${esc(p.journal||t('notProvided'))}</span></div>${institutionsHTML(p,true)}</article>`;}
function emptyList(){const weekly=view==='weekly';return `<div class="empty compact"><span class="empty-mark">${icon('book')}</span><h2>${t(weekly?'weeklyEmpty':state.papers.length?'emptyFilter':'emptyTitle')}</h2><p>${t(weekly?'weeklyEmptyText':state.papers.length?'emptyFilterText':'emptyText')}</p>${!state.papers.length?btn('nav',t('configure'),'arrow','primary small',`data-view="${weekly?'schedule':'settings'}"`):''}</div>`;}
function results(){const list=filtered();page=Math.min(page,Math.max(0,Math.ceil(list.length/40)-1));const p=list.find(p=>p.id===selected);return `<div class="paper-column"><div class="list-meta">${list.length} ${t('count')}</div><div class="paper-list">${list.length?(view==='weekly'?weeklyCards(list.slice(page*40,(page+1)*40)):list.slice(page*40,(page+1)*40).map(card).join('')):emptyList()}</div><div class="pagination">${btn('prev','','back','icon small',`aria-label="${t('prev')}" ${page===0?'disabled':''}`)}<span>${page+1}/${Math.max(1,Math.ceil(list.length/40))}</span>${btn('next','','arrow','icon small',`aria-label="${t('next')}" ${(page+1)*40>=list.length?'disabled':''}`)}</div></div>${p?detail(p):`<aside class="detail detail-placeholder"><div class="empty-mark">${icon('book')}</div><h2>${t('selectHint')}</h2></aside>`}`;}
function nativeMode(p){return /[\u3400-\u9fff]/.test((p.abstract||'').slice(0,200))?'zh':'en';}
function abstractHTML(p){const mode=abstractModes[p.id]||nativeMode(p),cache=p.abstractViewsSource===p.abstract?p.abstractViews||{}:{},content=mode===nativeMode(p)?p.abstract:cache[mode],busy=abstractBusy.has(p.id+':'+mode);return `<div class="abstract-heading"><h3>${t('abstract')}</h3><div class="abstract-tabs" role="group" aria-label="${t('abstractMode')}">${[['en','EN'],['zh','中'],['ds','AI']].map(([k,label])=>btn('abstract-mode',label,'',mode===k?'active':'',`data-mode="${k}" aria-pressed="${mode===k}" title="${k==='ds'?t('dsHelp'):label}"`)).join('')}</div></div><div class="abstract ${content?'rich-content':''}" ${content?`data-rich="${esc(content)}"`:''}>${busy?`<span class="spinner"></span> ${t('translating')}`:content?'':t(state.loadingAbstracts?.includes(p.id)?'abstractLoading':'abstractUnavailable')}</div>`;}
function detail(p){const c=corr(p),url=p.url||(p.doi?'https://doi.org/'+p.doi:'');return `<aside class="detail is-selected"><div class="detail-top row between"><span class="pill">${esc(p.journal||t('notProvided'))} · ${esc(p.year||t('notProvided'))}</span>${btn('detail-close','','close','ghost icon',`aria-label="${t('close')}"`)}</div><h2 class="paper-detail-title">${esc(p.title)}</h2><div class="authors">${authorHTML(p)}</div>${institutionsHTML(p)}<div class="paper-link"><span>${t('sourceLink')}</span>${url?`<a href="${esc(url)}" data-action="external" data-url="${esc(url)}">${esc(url)}</a>`:esc(t('notProvided'))}</div>${abstractHTML(p)}<div class="section-label">${t('keywords')}</div><div class="row wrap">${p.keywords.length?p.keywords.map(k=>`<span class="pill">${esc(k)}</span>`).join(''):`<span class="muted small-text">${t('notProvided')}</span>`}</div><div class="section-label">${t('corr')}</div><p class="small-text">${esc(c.join(', ')||t('notProvided'))}</p><details class="field"><summary class="small-text muted">${t('manual')}</summary><p class="help">${t('manualHelp')}</p>${p.authors.map((a,i)=>`<label class="author-option"><input type="checkbox" class="author-check" value="${i}" ${c.includes(a.name)?'checked':''}>${esc(a.name)}</label>`).join('')}<div class="row wrap">${btn('authors-save',t('authorSave'),'','small')}${btn('authors-reset',t('manualReset'),'','small ghost')}</div></details><div class="section-label">${t('tags')}</div><input id="tags-input" value="${esc(p.tags.join(', '))}" placeholder="${t('tagHint')}"><div class="row wrap field">${btn('tags-save',t('tagSave'),'tag','small')}${btn('star',t('saved'),'star',p.starred?'small star-toggle on':'small star-toggle',`data-id="${p.id}"`)}</div><div class="section-label">${t('source')}</div><p class="small-text muted">${esc(p.sources.join(' · '))}</p></aside>`;}
function keyField(id,has,root){return `<div class="field"><label for="${id}-key">${t(id==='serpapi'?'serp':id==='gpt'?'gptKey':'deepseek')}</label><input type="password" id="${id}-key" value="${esc(root[id+'Key']||'')}" autocomplete="off" placeholder="${t('keyHint')}"><div class="row between key-state"><span>${t(has?'keySaved':'keyMissing')}</span>${has?`<label class="checkbox"><input type="checkbox" id="clear-${id}" ${root[id==='serpapi'?'clearSerpapi':id==='gpt'?'clearGpt':'clearDeepseek']?'checked':''}>${t('clear')}</label>`:''}</div></div>`;}
function scheduleControls(){const s=state.settings;return `<section class="panel schedule-panel"><div class="row between wrap"><div><h2>${esc(scheduleLabel(draft||s))}</h2><p class="small-text muted">${t('nextRun')} · ${s.scheduleEnabled?date(state.nextRun):'—'}</p></div><div class="row wrap">${btn('toggle-schedule',t(s.scheduleEnabled?'disable':'enable'),'clock','primary')}${s.scheduleEnabled?btn('repair-schedule',t('repair'),'refresh'):''}</div></div>${scheduleFields(draft||s)}<p class="help">${t('scheduleHelp')}</p><span class="small-text muted">${esc(state.timezone)} · ${t(s.scheduleEnabled?'scheduleOn':'scheduleOff')}</span></section>`;}
function settings(){const root=draft||state.settings,s=view==='schedule'?root.weekly:root;return `<div class="page-heading"><div><h1>${t(view)}</h1><p>${t(view==='schedule'?'weeklyHelp2':'manualHelp2')}</p></div>${btn('save-settings',t('saveSettings'),'check','primary',state.running?'disabled':'')}</div><div class="scroll">${view==='schedule'?scheduleControls():''}<div class="settings-grid"><div>${authorConfig(s)}<section class="panel"><h2>${t('queriesTitle')}</h2><p class="help">${t('queriesHelp')}</p>${keywordGroupsHTML(s)}</section><section class="panel"><h2>${t('journalsTitle')}</h2><textarea id="journals" rows="4" placeholder="${t('journalPlaceholder')}">${esc(s.journals.join('\n'))}</textarea><div class="field"><label for="max-pages">${t('pages')}</label><input id="max-pages" type="number" min="1" max="50" value="${s.maxPages}"></div><p class="help">${t('pageHelp')}</p><div class="row between"><span class="muted small-text">${t('cost')}</span><strong id="cost">${s.groups.filter(g=>g.length).length*Math.max(1,s.journals.length)*s.maxPages}</strong></div></section></div><div><section class="panel"><h2>AI</h2><div class="field"><label for="ai-provider">${t('aiProvider')}</label><select id="ai-provider">${option('deepseek','DeepSeek',root.aiProvider)}${option('gpt','GPT (OpenAI)',root.aiProvider)}</select></div><p class="help">${t('aiScope')}</p></section><section class="panel"><h2>GPT (OpenAI)</h2>${keyField('gpt',state.hasGptKey,root)}<div class="field"><label for="gpt-model">${t('gptModel')}</label><input id="gpt-model" maxlength="104" value="${esc(root.gptModel||'gpt-4.1') }" placeholder="gpt-4.1"></div>${btn('test-gpt',t('testConnection'),'translate','small')}</section><section class="panel"><h2>DeepSeek</h2><p class="help">${t('deepseekHelp')}</p>${keyField('deepseek',state.hasDeepseekKey,root)}<div class="field"><label for="deepseek-model">${t('model')}</label><select id="deepseek-model">${option('deepseek-flash','DeepSeek Flash',root.deepseekModel)}${option('deepseek-v4-pro','DeepSeek V4 Pro',root.deepseekModel)}</select></div><div class="field">${btn('test-deepseek',t('testConnection'),'translate','small')}</div></section><section class="panel"><h2>SerpApi</h2><p class="help">${t('credentialsHelp')}</p>${keyField('serpapi',state.hasSerpKey,root)}<div class="field">${btn('test-serpapi',t('serpTest'),'translate','small')}</div><p class="footer-note">${t('protected')}</p></section><section class="panel"><h2>${t('dataTools')}</h2><p class="help">${t('dataHelp')}</p><div class="row wrap">${btn('backup',t('backup'),'download')}${btn('restore',t('restore'),'folder')}</div></section></div></div></div>`;}
function capture(){if(!editingSettings())return null;const root=JSON.parse(JSON.stringify(draft||state.settings)),config={groups:[0,1,2].map(i=>splitTerms($('#group-'+i).value)),groupNames:[0,1,2].map(i=>$('#group-name-'+i).value.trim()),journals:$('#journals').value.split('\n').map(x=>x.trim()).filter(Boolean),maxPages:Number($('#max-pages').value),authorName:$('#settings-author-name').value.trim(),authorSchool:$('#settings-author-school').value.trim(),authorRole:$('#settings-author-role').value,yearFrom:null,yearTo:null,monthFrom:$('#month-from')?.value||'',monthTo:$('#month-to')?.value||''};if(view==='schedule')root.weekly=config;else Object.assign(root,config);Object.assign(root,{scheduleDay:Number($('#schedule-day')?.value??root.scheduleDay??5),scheduleTime:$('#schedule-hour')?$('#schedule-hour').value+':'+$('#schedule-minute').value:(root.scheduleTime||'08:00'),language:state.settings.language,serpapiKey:$('#serpapi-key').value,deepseekKey:$('#deepseek-key').value,gptKey:$('#gpt-key').value,gptModel:$('#gpt-model').value.trim(),aiProvider:$('#ai-provider').value,clearGpt:!!$('#clear-gpt')?.checked,deepseekModel:$('#deepseek-model').value,clearSerpapi:!!$('#clear-serpapi')?.checked,clearDeepseek:!!$('#clear-deepseek')?.checked});return root;}
function splitTerms(s){return [...new Set(s.split(/[,，;；\n]/).map(x=>x.trim()).filter(Boolean))];}
function historyHTML(){return `<div class="page-heading"><div><h1>${t('history')}</h1><p>${t('historySub')}</p></div></div><div id="progress-zone">${progressHTML()}</div><div class="scroll">${state.runs.map(r=>`<article class="run-card"><div class="row between wrap"><strong>${date(r.startedAt)} · ${t(r.scheduled?'weekly':'manualRun')}</strong><span class="pill">${t(r.status)}</span></div><p>${r.added} ${t('added')} · ${r.received} ${t('received')} · ${r.pages||0} ${t('pageCount')}</p>${r.authorQuery?`<p>${esc(r.authorQuery.name)} · ${esc(r.authorQuery.school)} · ${t(r.authorQuery.role==='either'?'eitherRole':r.authorQuery.role==='first'?'first':'corr')}</p>`:''}${r.rejected?`<p>${r.rejected} ${t('authorExcluded')}</p>`:''}${r.error?`<p>${esc(message(r.error))}</p>`:''}</article>`).join('')||`<div class="empty"><h2>${t('noHistory')}</h2></div>`}</div>`;}
const chatSearchText=value=>String(value||'').normalize('NFKC').toLowerCase();
function chatSearchResults(){
  const terms=chatSearchText(chatSearch).trim().split(/\s+/).filter(Boolean);
  return state.chats.flatMap(chat=>{
    const questions=chat.messages.filter(m=>m.role==='user');
    const text=chatSearchText([chat.title,...questions.map(m=>m.content)].join(' '));
    if(!terms.every(term=>text.includes(term)))return [];
    const match=terms.length?questions.find(m=>terms.some(term=>chatSearchText(m.content).includes(term))):null;
    return [{chat,match}];
  });
}
function chatSearchSnippet(content){
  const text=content.replace(/\s+/g,' '),terms=chatSearchText(chatSearch).trim().split(/\s+/).filter(Boolean);
  const first=terms.map(term=>chatSearchText(text).indexOf(term)).filter(at=>at>=0).sort((a,b)=>a-b)[0]||0;
  const start=Math.max(0,first-24),end=Math.min(text.length,start+110);
  return (start?'…':'')+text.slice(start,end)+(end<text.length?'…':'');
}
function chatHistoryResultsHTML(){
  const results=chatSearchResults(),searching=!!chatSearch.trim();
  return `<div class="chat-search-count" role="status">${searching?wx('找到 '+results.length+' 条对话',results.length+' conversations found'):''}</div>`+
    (results.map(({chat:c,match})=>`<div class="chat-history-item ${chatId===c.id?'active':''}"><button class="chat-open ghost" data-action="chat-open" data-id="${esc(c.id)}" ${match?`data-message-id="${esc(match.id)}"`:''} title="${esc(c.title)}"><span>${esc(c.title)}</span>${match?`<span class="chat-match-snippet">${esc(chatSearchSnippet(match.content))}</span>`:''}<small>${date(c.updatedAt,true)}</small></button>${btn('rename-chat','','edit','ghost icon small',`data-id="${esc(c.id)}" aria-label="${t('rename')}" title="${t('rename')}"`)}${btn('delete-chat','','trash','ghost icon small',`data-id="${esc(c.id)}" aria-label="${u('deleteChat')}" title="${u('deleteChat')}" ${state.activeAi.includes(c.id)?'disabled':''}`)}</div>`).join('')||`<p class="help chat-search-empty">${searching?wx('没有找到相关历史问题，试试其他内容。','No matching past questions. Try different words.'):t('chatHelp')}</p>`);
}
function chatHistoryHTML(){
  const label=wx('搜索历史问题','Search past questions');
  return `<div class="eyebrow">${t('chatHistory')}</div><div class="chat-search"><label class="sr-only" for="chat-search">${label}</label><input id="chat-search" type="search" maxlength="500" value="${esc(chatSearch)}" placeholder="${wx('输入名称或提问内容…','Search names or question text…')}" aria-label="${label}" aria-controls="chat-history-results">${btn('clear-chat-search','','close','ghost icon small',`aria-label="${wx('清空历史搜索','Clear history search')}" title="${wx('清空历史搜索','Clear history search')}" ${chatSearch?'':'hidden'}`)}</div><div id="chat-history-results">${chatHistoryResultsHTML()}</div>`;
}
function renderChatHistory(){
  const results=$('#chat-history-results');if(!results)return;
  results.innerHTML=chatHistoryResultsHTML();
  $('[data-action="clear-chat-search"]').hidden=!chatSearch;
}
function positionChatMessages(){
  const messages=$('.chat-messages');if(!messages)return;
  const target=chatTargetMessage&&Array.from(messages.querySelectorAll('.chat-message.user')).find(el=>el.dataset.messageId===chatTargetMessage);
  if(target){target.classList.add('chat-search-target');if(target.scrollIntoView)target.scrollIntoView({block:'center'});}
  else messages.scrollTop=messages.scrollHeight;
}
function quickHTML(){const chat=state.chats.find(c=>c.id===chatId),busy=chatSending||state.activeAi.includes(chatId);return `<div class="page-heading"><div><h1>${t('quick')}</h1><p>${t('quickSub')}</p></div>${btn('new-chat',t('newChat'),'plus','small')}</div><div class="chat-layout"><aside class="chat-history panel">${chatHistoryHTML()}</aside><section class="chat-panel panel"><div class="chat-panel-top"><h2 title="${esc(chat?.title||wx('提问','Ask'))}">${esc(chat?.title||wx('提问','Ask'))}</h2><span class="pill">${aiLabel()}</span></div><div class="chat-messages" role="log">${chat?.messages.length?chat.messages.map(m=>`<article class="chat-message ${m.role}" data-message-id="${esc(m.id)}"><div class="message-role">${m.role==='user'?t('you'):aiLabel()}${m.role==='user'?btn('delete-question','','trash','ghost icon small',`data-id="${esc(chat.id)}" data-message-id="${esc(m.id)}" aria-label="${u('deleteQuestion')}" title="${u('deleteQuestion')}" ${busy?'disabled':''}`):''}</div><div class="message-content ${m.role==='assistant'&&m.status==='complete'?'rich-content':''}" ${m.role==='assistant'&&m.status==='complete'?`data-rich="${esc(m.content)}"`:''}>${m.role==='assistant'&&m.status==='complete'?'':m.status==='pending'?`<span class="spinner"></span> ${t('thinking')}`:m.status==='failed'?esc(message(m.error)):esc(m.content)}</div>${m.status==='failed'?btn('retry-chat',t('retry'),'refresh','small ghost',`data-id="${esc(chat.id)}"`):''}</article>`).join(''):`<div class="chat-welcome"><span class="welcome-icon">${icon('chat')}</span><h2>${t('chatEmpty')}</h2><p>${t('chatHelp')}</p></div>`}</div><div class="chat-composer"><textarea id="chat-input" rows="2" maxlength="12000" placeholder="${t('questionHint')}" ${busy?'disabled':''}>${esc(chatInput)}</textarea><div class="row between"><span class="small-text muted">${t('chatNote')}</span>${busy?btn('cancel-ai',t('stop'),'close','small',`data-id="${chatId||''}"`):btn('send-chat',t('ask'),'arrow','primary small')}</div></div></section></div>`;}
function modalHTML(){if(!modal)return '';if(['appearance','reset','weekly-export','balance','chat-delete','month-picker','date-picker','author-feedback'].includes(modal.kind))return controlsModal();return `<div class="modal-backdrop" data-action="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="row between"><h2 id="modal-title">${t('rename')}</h2>${btn('modal-close','','close','ghost icon',`id="modal-close" aria-label="${t('close')}"`)}</div><label class="modal-label" for="modal-name">${t('renameHint')}</label><input id="modal-name" maxlength="80" value="${esc(modal.title)}"><div class="row modal-actions">${btn('modal-close',t('cancel'))}${btn('save-chat-name',t('save'),'check','primary')}</div></section></div>`;}
function hydrate(){if(window.PaperDeskRichText)for(const el of $$('[data-rich]')){window.PaperDeskRichText.render(el,el.dataset.rich);el.removeAttribute('data-rich');}highlightReader();}
function render(){const dateFocus=modal?.kind==='date-picker'&&document.activeElement?.closest('.date-picker-modal')?document.activeElement.id:'';applyAppearance();const positions=['.paper-list','.detail','.scroll','.chat-history'].map(k=>[k,$(k)?.scrollTop||0]);document.documentElement.lang=state.settings.language==='zh'?'zh-CN':'en';$('#app').innerHTML=frame(view==='writing'?writingHTML():view==='quick'?quickHTML():editingSettings()?settings():view==='history'?historyHTML():research());hydrate();for(const [k,y]of positions)if($(k))$(k).scrollTop=y;if(view==='quick')positionChatMessages();if(modal&&typeof requestAnimationFrame==='function')requestAnimationFrame(()=>($('#modal-name')||(dateFocus&&$('#'+dateFocus))||$('#modal-close'))?.focus());}
function renderResults(){if($('#results-zone')){$('#results-zone').innerHTML=results();hydrate();}}
async function navigate(next){if(editingSettings()){draft=capture();await flushGroupRenames();}if(!['inbox','quick','writing','weekly','all','saved','settings','schedule','history'].includes(next))return;view=next;selected=null;page=0;filter='';groupFilter='';journalFilter='';authorFilter='';tagFilter='';unreadOnly=false;activeAuthorQuery=null;render();if(view==='writing')$('.writing-page').scrollTop=0;}
function openModal(value){if(editingSettings())draft=capture();modal={...value,focus:document.activeElement?.dataset.action,focusId:value.focusId||document.activeElement?.id};render();}
function closeModal(){const focus=modal?.focus,focusId=modal?.focusId;modal=null;render();if(focusId)$('#'+focusId)?.focus();else if(focus)$(`[data-action="${focus}"]`)?.focus();}
async function sendChat(){const question=chatInput.trim();if(!question||chatSending)return;if(!hasAIKey()){await navigate('settings');toast(message(state.settings.aiProvider==='gpt'?'GPT_KEY_REQUIRED':'DEEPSEEK_KEY_REQUIRED'));return;}chatSending=true;chatInput='';chatTargetMessage=null;render();try{const result=await call('chat-send',{id:chatId,question});chatId=result.id;state=normalState(await call('get-state'));if(result.error)toast(message(result.error));}catch(e){chatInput=question;toast(message(e.message));}finally{chatSending=false;if(view==='quick'){render();$('#chat-input')?.focus();}}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();const a=b.dataset.action,p=state.papers.find(x=>x.id===selected);try{if(await additionalAction(a,b,e))return;
 if(a==='nav')return await navigate(b.dataset.view);
 if(await writingAction(a,b))return;
 if(a==='test-gpt'){b.disabled=true;await call('test-gpt',{key:$('#gpt-key').value,model:$('#gpt-model').value.trim()});toast(t('connectionOK'));return;}
 if(a==='language'){if(editingSettings())draft=capture();await call('language',state.settings.language==='zh'?'en':'zh');state=normalState(await call('get-state'));if(draft)draft.language=state.settings.language;render();return;}
 if(a==='run'||a==='run-weekly'||a==='author-search'){if(!state.hasSerpKey){await navigate('settings');toast(message('SERPAPI_KEY_REQUIRED'));return;}if(a==='author-search'){authorQuery={name:$('#author-name').value,school:$('#author-school').value,role:$('#author-role').value};if(!authorQuery.name.trim())throw Error('INVALID_AUTHOR_SEARCH');activeAuthorQuery={...authorQuery};selected=null;renderResults();await call(a,authorQuery);}else {activeAuthorQuery=null;await call(a);}return;}
 if(a==='clear-author'){activeAuthorQuery=null;render();return;}
 if(a==='stop'){await call('cancel');return;}
 if(a==='select'){selected=b.dataset.id;renderResults();await call('paper-update',{id:selected,read:true});call('load-abstract',selected).catch(e=>toast(message(e.message)));return;}
 if(a==='detail-close'){selected=null;renderResults();return;}
 if(a==='prev'||a==='next'){page+=a==='next'?1:-1;renderResults();return;}
 if(a==='unread'){unreadOnly=!unreadOnly;selected=null;render();return;}
 if(a==='star'){const item=state.papers.find(p=>p.id===b.dataset.id);await call('paper-update',{id:item.id,starred:!item.starred});return;}
 if(a==='save-settings'){const input=capture();await flushGroupRenames();await call('save-settings',input);state=normalState(await call('get-state'));draft=null;render();toast(t('savedOK'));return;}
 if(a==='toggle-schedule'||a==='repair-schedule'){draft=capture();await flushGroupRenames();b.disabled=true;if(a==='repair-schedule'||!state.settings.scheduleEnabled){await call('save-settings',draft);draft=null;}await call('schedule',a==='repair-schedule'||!state.settings.scheduleEnabled);state=normalState(await call('get-state'));render();return;}
 if(a==='test-deepseek'){b.disabled=true;await call('test-deepseek',{key:$('#deepseek-key').value});toast(t('connectionOK'));return;}
 if(a==='test-serpapi'){b.disabled=true;const result=await call('test-serpapi',{key:$('#serpapi-key').value});toast(t('serpOK')+result.remaining);return;}
 if(a==='external'){await call('open-external',b.dataset.url);return;}
 if(a==='export'||a==='backup'){if(await call('export',a==='export'?'csv':'json'))toast(t('savedOK'));return;}
 if(a==='restore'){const n=await call('import');if(n!==false)toast(t('imported')+': '+n);return;}
 if(a==='tags-save'){await call('paper-update',{id:selected,tags:splitTerms($('#tags-input').value)});return;}
 if(a==='authors-save'){await call('paper-update',{id:selected,manualCorresponding:$$('.author-check:checked').map(el=>p.authors[Number(el.value)].name)});return;}
 if(a==='authors-reset'){await call('paper-update',{id:selected,manualCorresponding:null});return;}
 if(a==='modal-close'||a==='modal-backdrop'&&e.target===b){closeModal();return;}
 if(a==='clear-chat-search'){chatSearch='';$('#chat-search').value='';renderChatHistory();$('#chat-search').focus();return;}
 if(a==='new-chat'){if(chatSending)return;chatId=null;chatInput='';chatTargetMessage=null;render();$('#chat-input')?.focus();return;}
 if(a==='chat-open'){if(chatSending)return;chatId=b.dataset.id;chatInput='';chatTargetMessage=b.dataset.messageId||null;render();return;}
 if(a==='send-chat'){await sendChat();return;}
 if(a==='cancel-ai'){await call('ai-cancel',b.dataset.id);return;}
 if(a==='retry-chat'){const chat=state.chats.find(c=>c.id===b.dataset.id);chatId=chat.id;chatInput=[...chat.messages].reverse().find(m=>m.role==='user')?.content||'';render();return;}
 if(a==='rename-chat'){const c=state.chats.find(c=>c.id===b.dataset.id);openModal({kind:'rename',id:c.id,title:c.title});return;}
 if(a==='save-chat-name'){await call('chat-rename',{id:modal.id,title:$('#modal-name').value});state=normalState(await call('get-state'));closeModal();return;}
 if(a==='abstract-mode'){const id=selected,mode=b.dataset.mode;abstractModes[id]=mode;renderResults();if(mode===nativeMode(p)||p.abstractViewsSource===p.abstract&&p.abstractViews?.[mode])return;const token=id+':'+mode;if(abstractBusy.has(token))return;abstractBusy.add(token);renderResults();try{await call('abstract-view',{id,mode});state=normalState(await call('get-state'));}catch(e){toast(message(e.message));abstractModes[id]=nativeMode(p);}finally{abstractBusy.delete(token);if(selected===id)renderResults();}return;}
 }catch(e){toast(message(e.message));}finally{if(b.isConnected)b.disabled=false;}
});
document.addEventListener('toggle',e=>{if(e.target.classList?.contains('author-search'))authorOpen=e.target.open;},true);
document.addEventListener('input',e=>{const id=e.target.id;captureWritingField(e.target);if(id==='chat-input')chatInput=e.target.value;if(id==='chat-search'){chatSearch=e.target.value;renderChatHistory();}if(id==='filter'){filter=e.target.value;page=0;renderResults();}if(id==='author-name')authorQuery.name=e.target.value;if(id==='author-school')authorQuery.school=e.target.value;if(editingSettings()&&(e.target.classList.contains('group-input')||['journals','max-pages'].includes(id))){const d=capture(),s=view==='schedule'?d.weekly:d;for(let i=0;i<3;i++)$('#group-count-'+i).textContent=(s.groups[i]?.length||0)+'/5';$('#cost').textContent=s.groups.filter(g=>g.length).length*Math.max(1,s.journals.length)*s.maxPages;}});
document.addEventListener('change',e=>{const v=e.target.value;switch(e.target.id){case'writing-type':case'writing-provider':case'writing-target':captureWritingField(e.target);return;case'author-role':authorQuery.role=v;return;case'group-filter':groupFilter=v;break;case'journal-filter':journalFilter=v;break;case'author-filter':authorFilter=v;break;case'tag-filter':tagFilter=v;break;case'sort':sort=v;break;default:return;}page=0;selected=null;renderResults();});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('paper-card')){e.preventDefault();e.target.click();}if(e.key==='Escape'){if(e.target.id==='chat-search'){chatSearch='';e.target.value='';renderChatHistory();return;}if(modal)closeModal();else if(selected){selected=null;renderResults();}}if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendChat();}if(modal&&e.key==='Enter'&&e.target.id==='modal-name')$('[data-action="save-chat-name"]')?.click();if(modal&&e.key==='Tab'){const els=$$('.modal button:not(:disabled),.modal input:not(:disabled),.modal select:not(:disabled)');if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0]?.focus();}}});
window.desk.on('state',s=>{state=normalState(s);if(chatSending&&!chatId)chatId=state.chats[0]?.id||null;if(editingSettings())return;if(document.activeElement?.matches('input,textarea,select')){if(view==='quick')renderChatHistory();if(researchView())renderResults();return;}render();});
window.desk.on('progress',p=>{state.progress=p;state.running=true;if($('#progress-zone'))$('#progress-zone').innerHTML=progressHTML();});
window.desk.on('error',code=>toast(message(code)));
call('get-state').then(s=>{state=normalState(s);render();}).catch(e=>{$('#app').textContent=e.message;});

window.desk.on('export-progress',p=>toast((state.settings.language==='zh'?'正在导出':'Exporting')+' '+p.current+'/'+p.total+' · '+p.week));
